/* Firmware nhay LED tren ATmega328P — LED o chan PB5.
 * Yeu cau: FR-01 - Nhay LED o chan PB5, chu ky 1 giay mot lan.
 */
#include <avr/io.h>

void setup() {
    // Dat chan PB5 lam output
    DDRB |= (1 << PB5);
}

void loop() {
    // Dao trang thai PB5
    PORTB ^= (1 << PB5);
    // Cho 1000 ms (1 giay)
    delay(1000);
}

#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

/* Mo phong hanh vi dieu khien nhay LED tren PB5 */
