    const double nguong_ms = 1000.0;

    bool dat = (chu_ky_dao_ms == nguong_ms);

    /* In ket qua mo phong dang JSON cho sim.run doc */
    printf("{\n");
    printf("  \"dat\": %s,\n", dat ? "true" : "false");
    printf("  \"passed\": %s,\n", dat ? "true" : "false");
    printf("  \"asserts\": [\n");
    printf("    {\n");
    printf("      \"ma\": \"A1\",\n");
    printf("      \"id\": \"A1\",\n");
    printf("      \"gia_tri\": %.1f,\n", chu_ky_dao_ms);
    printf("      \"value\": %.1f,\n", chu_ky_dao_ms);
    printf("      \"nguong\": %.1f,\n", nguong_ms);
    printf("      \"don_vi\": \"ms\",\n");
    printf("      \"dat\": %s,\n", dat ? "true" : "false");
    printf("      \"passed\": %s\n", dat ? "true" : "false");
    printf("    }\n");
    printf("  ]\n");
    printf("}\n");

    return 0;
}

