#include <stdint.h>

/* 1. Them 'volatile': bao trinh bien dich luon doc gia tri tu RAM, khong cache tren thanh ghi */
static volatile uint32_t so_xung = 0;

/* Ham khoa/mo ngat (ho tro ca ARM Cortex-M va moi truong gia lap tren may tinh) */
static inline void khoa_ngat(void)
{
#if defined(__arm__) || defined(__thumb__)
    __asm__ volatile ("cpsid i" ::: "memory");
#endif
}

static inline void mo_ngat(void)
{
#if defined(__arm__) || defined(__thumb__)
    __asm__ volatile ("cpsie i" ::: "memory");
#endif
}

void EXTI0_IRQHandler(void)
{
    so_xung++;
}

/* 2. Doc so xung nguyen tu (atomic) trong vung gang, tranh bi rach du lieu 32 bit */
uint32_t doc_so_xung(void)
{
    uint32_t gia_tri;
    khoa_ngat();
    gia_tri = so_xung;
    mo_ngat();
    return gia_tri;
}

/* 3. Kiem tra va dat lai so xung trong cung mot vung gang de tranh mat xung xay ra trong tich tac */
uint32_t lay_va_xoa_neu_qua_nguong(uint32_t nguong)
{
    uint32_t da_dem = 0;
    khoa_ngat();
    if (so_xung > nguong) {
        da_dem = so_xung;
        so_xung = 0;
    }
    mo_ngat();
    return da_dem;
}

