# -*- coding: utf-8 -*-
"""`target.erase` — công cụ do TÁC TỬ tự viết.

Xoá toàn bộ bộ nhớ Flash của chip đích kết nối qua bộ nạp.
"""

from __future__ import annotations

import shutil
import subprocess
import time
from typing import Any, Dict


def thuc_thi_erase(timeout_s: float = 30.0) -> Dict[str, Any]:
    """Thực thi lệnh mass erase qua st-flash và đo lường kết quả."""
    st_flash = shutil.which("st-flash")
    if not st_flash:
        return {
            "ok": False,
            "trang_thai": "khong_tim_thay_cong_cu",
            "thoi_gian_ms": None,
            "thong_bao": "Không tìm thấy công cụ `st-flash` trên PATH hệ thống.",
        }

    t0 = time.perf_counter()
    try:
        proc = subprocess.run(
            [st_flash, "erase"],
            capture_output=True,
            text=True,
            timeout=timeout_s,
        )
        elapsed_ms = round((time.perf_counter() - t0) * 1000, 2)
        raw_output = (proc.stdout + "\n" + proc.stderr).strip()

        if proc.returncode == 0:
            return {
                "ok": True,
                "trang_thai": "thanh_cong",
                "thoi_gian_ms": elapsed_ms,
                "ma_thoat": proc.returncode,
                "dau_ra": raw_output,
                "thong_bao": "Đã hoàn thành xoá toàn bộ Flash của chip qua st-flash erase.",
            }
        else:
            return {
                "ok": False,
                "trang_thai": "loi_lenh",
                "thoi_gian_ms": elapsed_ms,
                "ma_thoat": proc.returncode,
                "dau_ra": raw_output,
                "thong_bao": f"st-flash erase thất bại với mã {proc.returncode}.",
            }
    except subprocess.TimeoutExpired:
        elapsed_ms = round((time.perf_counter() - t0) * 1000, 2)
        return {
            "ok": False,
            "trang_thai": "qua_thoi_gian",
            "thoi_gian_ms": elapsed_ms,
            "thong_bao": f"Quá thời gian chờ khi chạy st-flash erase.",
        }
    except Exception as exc:
        elapsed_ms = round((time.perf_counter() - t0) * 1000, 2)
        return {
            "ok": False,
            "trang_thai": "ngoai_le",
            "thoi_gian_ms": elapsed_ms,
            "thong_bao": f"Ngoại lệ khi thực thi st-flash erase: {exc}",
        }


def dang_ky(r) -> None:
    @r.tool(
        "target.erase",
        "Mạch thật",
        "Xoá toàn bộ bộ nhớ Flash của chip đích kết nối qua bộ nạp.",
        {"type": "object", "properties": {}, "required": []},
        risk="R1",
        core=False,
        keywords=["erase", "xoa", "flash", "mass-erase", "st-flash"],
    )
    def target_erase(ctx: Any, **kwargs) -> Dict[str, Any]:
        return thuc_thi_erase()

#ifndef CONTROL_H
#define CONTROL_H

#include <stdint.h>

typedef struct {
    uint8_t state;
} led_control_t;

void led_control_init(led_control_t *ctrl);
void led_control_toggle(led_control_t *ctrl);
uint8_t led_control_get_state(const led_control_t *ctrl);

#endif /* CONTROL_H */

#include "control.h"

void led_control_init(led_control_t *ctrl)
{
    if (ctrl != 0) {
        ctrl->state = 0;
    }
}

void led_control_toggle(led_control_t *ctrl)
{
    if (ctrl != 0) {
        ctrl->state = (ctrl->state == 0) ? 1 : 0;
    }
}

uint8_t led_control_get_state(const led_control_t *ctrl)
{
    if (ctrl != 0) {
        return ctrl->state;
    }
    return 0;
}

/* Nhay LED tren ATmega328P — LED o chan PB5. */
#include <stdint.h>
#include "control.h"

#define DDRB  (*(volatile uint8_t *)0x24)
#define PORTB (*(volatile uint8_t *)0x25)

static void cho(uint32_t n)
{
    while (n--) { __asm__ __volatile__("nop"); }
}

int main(void)
{
    led_control_t led;
    led_control_init(&led);

    DDRB |= (1 << 5);
    while (1) {
        led_control_toggle(&led);
        if (led_control_get_state(&led)) {
            PORTB |= (1 << 5);
        } else {
            PORTB &= ~(1 << 5);
        }
        cho(1000000);
    }
}

#include <stdio.h>
#include <assert.h>

#if __has_include("firmware/control.h")
#include "firmware/control.h"
#else
#include "control.h"
#endif

static void test_led_init(void)
{
    led_control_t led;
    led.state = 99;
    led_control_init(&led);
    assert(led_control_get_state(&led) == 0);
}

static void test_led_toggle(void)
{
    led_control_t led;
    led_control_init(&led);

    led_control_toggle(&led);
    assert(led_control_get_state(&led) == 1);

    led_control_toggle(&led);
    assert(led_control_get_state(&led) == 0);
}

static void test_led_null(void)
{
    led_control_init(0);
    led_control_toggle(0);
    assert(led_control_get_state(0) == 0);
}

int main(void)
{
    test_led_init();
    test_led_toggle();
    test_led_null();
    printf("3 tests passed\n");
    return 0;
}

