    bool c3 = (led_control_get_state(0) == 0);

    printf("{\"ca\": [{\"ten\": \"khoi tao LED ve trang thai tat\", \"dat\": %s, \"vi\": \"state == 0\"}, {\"ten\": \"dao trang thai LED\", \"dat\": %s, \"vi\": \"tat -> bat -> tat\"}, {\"ten\": \"xu ly con tro null an toan\", \"dat\": %s, \"vi\": \"khong crash va tra ve 0\"}]}\n",
           c1 ? "true" : "false",
           c2 ? "true" : "false",
